#!/usr/bin/env node
// The iOS shell's copy of the on-device request contract, built from the
// Node sources and never written by hand (MULTIPLATFORM-SHELL-2026-10-17.md
// §4.3). The CommonJS files POST /api/device-model/chat runs on the Mac
// (device-model.js → chat.js → humanizer.js, system-integrity.js,
// model-task-runtime.js) are wrapped with a minimal require() into one
// classic script that installs `globalThis.AISystem6DeviceRequest`; the shell
// runs it in JavaScriptCore (platform/apple/AISystem6Core, ShellContract).
//
// Beside the bundle it writes device-request.cases.json: fixed inputs and the
// answers the ORIGINAL Node modules give for them. The node contract
// (tests/features/ios-shell-device-request.test.mjs) proves the bundle run in
// node:vm answers byte for byte the same; the Swift test proves
// JavaScriptCore does too. Drift in either place fails a check instead of
// silently loosening a guardrail.
//
//   node tooling/build-device-request-bundle.mjs [--out <dir>]
//
// Default out: platform/ios/AISystem6Shell/Generated (git-ignored). No
// network, no build step, deterministic: the same sources give the same bytes.

import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join, posix, relative } from "node:path";
import { Readable } from "node:stream";
import { fileURLToPath, pathToFileURL } from "node:url";

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), "..");
export const ENTRY = "tooling/lib/device-request-entry.cjs";
export const GLOBAL_NAME = "AISystem6DeviceRequest";
export const DEFAULT_OUT = "platform/ios/AISystem6Shell/Generated";

// Node built-ins the server modules name at load time. Nothing reachable from
// the entry calls them; the shims keep module evaluation total and make any
// call fail loudly instead of pretending a helper process exists.
const BUILTIN_SHIMS = Object.freeze({
  "node:fs": "{ accessSync() { throw new Error('no file system access in the shell contract'); }, constants: { R_OK: 4, X_OK: 1 } }",
  "node:path": "{ resolve: (...parts) => parts.join('/'), join: (...parts) => parts.join('/') }",
  "node:child_process": "{ spawn() { throw new Error('no processes in the shell contract'); } }",
});
// Generated from private editorial sources; the three device tasks and the
// task contracts never read it (only prompt builders do), so the bundle
// carries none of it. The parity contract proves the answers do not change.
const DATA_STUBS = Object.freeze({
  "apps/desktop/app/generated/ai-prompt-files.json": "[]",
});

const requirePattern = /\brequire\(\s*(["'])([^"']+)\1\s*\)/g;

/** @param {string} id repo-relative module path */
function readModule(id) {
  return readFileSync(join(repoRoot, id), "utf8");
}

/**
 * Walk the require graph from the entry. Every specifier must resolve to a
 * repo file, a shimmed built-in or a stubbed data file; anything else stops
 * the build.
 */
export function collectModules(entry = ENTRY) {
  /** @type {Map<string, { source: string, deps: Record<string, string> }>} */
  const modules = new Map();
  const queue = [entry];
  while (queue.length) {
    const id = /** @type {string} */ (queue.shift());
    if (modules.has(id)) continue;
    const source = readModule(id);
    /** @type {Record<string, string>} */
    const deps = {};
    for (const match of source.matchAll(requirePattern)) {
      const spec = match[2];
      if (Object.hasOwn(BUILTIN_SHIMS, spec)) {
        deps[spec] = spec;
        continue;
      }
      if (!spec.startsWith(".")) throw new Error(`${id}: require("${spec}") is neither relative nor a shimmed built-in`);
      const target = posix.normalize(posix.join(posix.dirname(id), spec));
      deps[spec] = target;
      if (Object.hasOwn(DATA_STUBS, target)) continue;
      if (!target.endsWith(".js") && !target.endsWith(".cjs")) throw new Error(`${id}: require("${spec}") is not a script`);
      queue.push(target);
    }
    modules.set(id, { source, deps });
  }
  return modules;
}

/** One classic script, deterministic for the same inputs. */
export function bundleDeviceRequest() {
  const modules = collectModules();
  const ids = [...modules.keys()].sort();
  const inputs = ids.map((id) => ({ id, sha256: createHash("sha256").update(modules.get(id).source).digest("hex") }));
  const lines = [
    "// GENERATED by tooling/build-device-request-bundle.mjs. Do not edit; rebuild.",
    "// The on-device request contract of POST /api/device-model/chat for the iOS shell.",
    ...inputs.map((input) => `// input ${input.id} sha256:${input.sha256}`),
    "(function (globalScope) {",
    "  var definitions = Object.create(null);",
    "  var cache = Object.create(null);",
    "  var builtins = Object.create(null);",
    ...Object.entries(BUILTIN_SHIMS).map(([name, shim]) => `  builtins[${JSON.stringify(name)}] = ${shim};`),
    "  var stubs = Object.create(null);",
    ...Object.entries(DATA_STUBS).map(([name, value]) => `  stubs[${JSON.stringify(name)}] = ${value};`),
    "  function load(id) {",
    "    if (Object.prototype.hasOwnProperty.call(builtins, id)) return builtins[id];",
    "    if (Object.prototype.hasOwnProperty.call(stubs, id)) return stubs[id];",
    "    if (cache[id]) return cache[id].exports;",
    "    var definition = definitions[id];",
    "    if (!definition) throw new Error('module not bundled: ' + id);",
    "    var module = { exports: {} };",
    "    cache[id] = module;",
    "    var dirname = id.slice(0, id.lastIndexOf('/'));",
    "    definition.factory(module, module.exports, function (spec) {",
    "      if (!Object.prototype.hasOwnProperty.call(definition.deps, spec)) throw new Error(id + ': unbundled require ' + spec);",
    "      return load(definition.deps[spec]);",
    "    }, '/bundle/' + dirname, '/bundle/' + id);",
    "    return module.exports;",
    "  }",
  ];
  for (const id of ids) {
    const { source, deps } = modules.get(id);
    lines.push(`  definitions[${JSON.stringify(id)}] = { deps: ${JSON.stringify(deps)}, factory: function (module, exports, require, __dirname, __filename) {`);
    lines.push(source.replace(/\s+$/, ""));
    lines.push("  } };");
  }
  lines.push(`  globalScope.${GLOBAL_NAME} = load(${JSON.stringify(ENTRY)});`);
  lines.push("})(typeof globalThis !== 'undefined' ? globalThis : this);");
  return { source: `${lines.join("\n")}\n`, inputs };
}

// ---- parity cases ----------------------------------------------------------

const ask = (extra = {}) => ({
  ai_system6_task_kind: "three-questions",
  language: "en",
  messages: [{ role: "user", content: "I keep putting off the essay about my grandfather." }],
  ...extra,
});

/** Inputs only; the expected answers come from the original modules. */
export const caseInputs = Object.freeze({
  prepare: [
    { name: "three questions, en", body: ask() },
    { name: "three questions, zh-Hant, temperature", body: ask({ language: "zh-TW", temperature: 0.4, messages: [{ role: "user", content: "我一直拖着写外公的那篇。" }] }) },
    { name: "side question, zh-Hans, two turns", body: ask({ ai_system6_task_kind: "side-question", language: "zh-CN", messages: [{ role: "user", content: "这一段讲清楚了吗？" }, { role: "assistant", content: "哪一段？" }, { role: "user", content: "第二段。" }] }) },
    { name: "title, text parts", body: ask({ ai_system6_task_kind: "title", messages: [{ role: "user", content: [{ type: "text", text: "Notes on the move" }, "to Taipei"] }] }) },
    { name: "max tokens clamp", body: ask({ max_tokens: 99999 }) },
    { name: "longer than any window", body: ask({ messages: [{ role: "user", content: "a long draft ".repeat(4000) }] }) },
    { name: "drafting task refused", body: ask({ ai_system6_task_kind: "writing-tool" }) },
    { name: "no messages", body: ask({ messages: [] }) },
    { name: "image part", body: ask({ messages: [{ role: "user", content: [{ type: "image_url", image_url: { url: "data:," } }] }] }) },
    { name: "only a system message", body: ask({ messages: [{ role: "system", content: "x" }] }) },
    { name: "built-in, ask-only door", body: ask({ engine: "mlx", top_p: 0.8, seed: 7 }) },
    { name: "built-in, named model", body: ask({ engine: "mlx", model: "qwen3.5-0.8b-4bit" }) },
    { name: "built-in, general chat", body: { engine: "mlx", ai_system6_task_kind: "chat", language: "en", messages: [{ role: "system", content: "Be brief." }, { role: "user", content: "Hi" }, { role: "assistant", content: "Hello." }, { role: "user", content: "Where did this start?" }] } },
    { name: "built-in, general chat, not streamed", body: { engine: "mlx", stream: false, messages: [{ role: "user", content: "Hi" }] } },
    { name: "built-in, general chat with tools", body: { engine: "mlx", tools: [{ type: "function" }], messages: [{ role: "user", content: "Hi" }] } },
    { name: "built-in, general chat with schema", body: { engine: "mlx", response_format: { type: "json_object" }, messages: [{ role: "user", content: "Hi" }] } },
    { name: "built-in, general chat ends on assistant", body: { engine: "mlx", messages: [{ role: "user", content: "Hi" }, { role: "assistant", content: "Hello." }] } },
    { name: "wrong content type", body: ask(), contentType: "text/plain" },
    { name: "invalid JSON", raw: "{nope", contentType: "application/json" },
    { name: "array body", raw: "[]", contentType: "application/json" },
    { name: "empty body", raw: "", contentType: "application/json" },
    { name: "too large", raw: JSON.stringify(ask({ messages: [{ role: "user", content: "x".repeat(1024 * 1024) }] })), contentType: "application/json" },
  ],
  status: [
    { name: "apple ready, size unknown", raw: { available: true, reason: null, contextSize: null, os: "26.0", locales: { en: true } } },
    { name: "apple ready, size 4096", raw: { available: true, contextSize: 4096, contextSizeSource: "system" } },
    { name: "apple not eligible", raw: { available: false, reason: "deviceNotEligible", os: "26.0" } },
    { name: "apple, zero size", raw: { available: true, contextSize: 0 } },
    { name: "apple, garbage", raw: { available: "yes", reason: 3 } },
  ],
  builtInStatus: [
    { name: "nothing downloaded", raw: { engine: "mlx", available: false, reason: "noModelDownloaded", installed: [], runnable: [] } },
    { name: "simulator", raw: { engine: "mlx", available: false, reason: "simulator", installed: [], runnable: [] } },
    { name: "default model runnable", raw: { engine: "mlx", available: true, reason: null, installed: ["qwen3.5-4b-4bit"], runnable: ["qwen3.5-4b-4bit"], vision: ["qwen3.5-4b-4bit"], contextTokens: { "qwen3.5-4b-4bit": 16384 } } },
    { name: "only a small model", raw: { engine: "mlx", available: true, runnable: ["qwen3.5-0.8b-4bit"], contextTokens: { "qwen3.5-0.8b-4bit": 8192 } } },
    { name: "memory gate", raw: { engine: "mlx", available: false, reason: "memoryGate", installed: ["qwen3.5-4b-4bit"], runnable: [] } },
  ],
  helperErrors: [
    ["exceededContextWindowSize", "", null], ["guardrailViolation", "x", null], ["refusal", "", null],
    ["unsupportedLanguageOrLocale", "", null], ["rateLimited", "", null], ["concurrentRequests", "", null],
    ["consentRequired", "", null], ["memoryGate", "needs 3 GB", null], ["unavailable", "", "modelNotReady"],
    ["unavailable", "", null], ["badRequest", "prompt is required", null], ["badRequest", "", null],
    ["cancelled", "cancelled", null], ["other", "timeout", null],
  ],
});

/** The original Node modules, loaded fresh from the repo. */
function originals() {
  const require = createRequire(pathToFileURL(join(repoRoot, "tooling/build-device-request-bundle.mjs")));
  return {
    device: require("../apps/server/server/device-model.js"),
    http: require("../apps/server/server/lib/http.js"),
  };
}

/** What the route answers before any engine runs, with the route's own functions. */
async function originalPrepare({ device, http }, item) {
  const raw = item.raw ?? JSON.stringify(item.body);
  const contentType = item.contentType ?? "application/json";
  const bytes = Buffer.from(raw, "utf8");
  const req = Readable.from(bytes.length ? [bytes] : []);
  Object.assign(req, { method: "POST", headers: { "content-type": contentType, "content-length": String(bytes.length) } });
  try {
    const body = await http.readJsonBody(req, { limitBytes: 1024 * 1024 });
    const plan = device.planDeviceChat(body);
    return {
      ok: true,
      plan: {
        taskKind: plan.taskKind,
        engine: plan.engine,
        general: plan.general,
        stream: plan.stream,
        modelId: plan.modelId,
        request: plan.request,
        estimatedTokens: plan.estimatedTokens,
        replyTokens: plan.replyTokens,
      },
    };
  } catch (error) {
    /** @type {{ status: number, body: any }} */
    const sent = { status: 0, body: null };
    const res = { destroyed: false, writableEnded: false, writeHead(status) { sent.status = status; }, end(text) { sent.body = JSON.parse(text); } };
    if (http.respondIfClientError(res, error)) return { ok: false, status: sent.status, body: sent.body };
    return { ok: false, status: 502, body: { code: "device_failed", error: "The on-device model stopped without an answer." } };
  }
}

/**
 * Inputs plus the original modules' answers, as exact JSON strings (the
 * comparison is on bytes, not on parsed values).
 */
export async function buildCases() {
  const mods = originals();
  const prepare = [];
  for (const item of caseInputs.prepare) {
    const raw = item.raw ?? JSON.stringify(item.body);
    prepare.push({
      name: item.name,
      raw,
      contentType: item.contentType ?? "application/json",
      byteLength: Buffer.byteLength(raw, "utf8"),
      expected: JSON.stringify(await originalPrepare(mods, item)),
    });
  }
  const appleShaped = caseInputs.status.map((item) => ({ name: item.name, raw: JSON.stringify(item.raw), expected: JSON.stringify(mods.device.shapeAppleStatus(item.raw)) }));
  const builtInShaped = caseInputs.builtInStatus.map((item) => ({ name: item.name, raw: JSON.stringify(item.raw), expected: JSON.stringify(mods.device.shapeBuiltInStatus(item.raw)) }));
  const combined = [];
  for (const apple of caseInputs.status) {
    for (const builtIn of caseInputs.builtInStatus) {
      const a = mods.device.shapeAppleStatus(apple.raw);
      const b = mods.device.shapeBuiltInStatus(builtIn.raw);
      combined.push({ name: `${apple.name} + ${builtIn.name}`, apple: JSON.stringify(a), builtIn: JSON.stringify(b), expected: JSON.stringify(mods.device.combinedDeviceStatus(a, b)) });
    }
  }
  const refusal = [];
  for (const item of prepare) {
    const prepared = JSON.parse(item.expected);
    if (!prepared.ok) continue;
    const statuses = prepared.plan.engine === "mlx" ? builtInShaped : appleShaped;
    for (const status of statuses) {
      refusal.push({
        name: `${item.name} / ${status.name}`,
        plan: JSON.stringify(prepared.plan),
        status: status.expected,
        expected: JSON.stringify(mods.device.deviceChatRefusal(prepared.plan, JSON.parse(status.expected))),
      });
    }
  }
  const helperErrors = caseInputs.helperErrors.map(([code, message, reason]) => ({
    code, message, reason,
    expected: JSON.stringify(mods.device.mapHelperError(code, message, reason == null ? undefined : reason)),
  }));
  return { prepare, appleStatus: appleShaped, builtInStatus: builtInShaped, combined, refusal, helperErrors };
}

export async function writeDeviceRequestBundle(outDir = join(repoRoot, DEFAULT_OUT)) {
  const { source, inputs } = bundleDeviceRequest();
  const cases = await buildCases();
  mkdirSync(outDir, { recursive: true });
  writeFileSync(join(outDir, "device-request.js"), source);
  writeFileSync(join(outDir, "device-request.cases.json"), `${JSON.stringify({ global: GLOBAL_NAME, inputs, ...cases }, null, 2)}\n`);
  return { outDir, bytes: Buffer.byteLength(source), inputs, cases };
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const index = process.argv.indexOf("--out");
  const outDir = index > 0 ? join(process.cwd(), process.argv[index + 1]) : join(repoRoot, DEFAULT_OUT);
  const result = await writeDeviceRequestBundle(outDir);
  console.log(`device-request.js: ${result.bytes} bytes from ${result.inputs.length} modules → ${relative(repoRoot, result.outDir) || "."}`);
  const counts = Object.entries(result.cases).map(([key, list]) => `${key} ${list.length}`).join(", ");
  console.log(`device-request.cases.json: ${counts}`);
}
